// ResutoMCP: clients, tools, approvals.
// Owner: Agent E2 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
//
// External AI clients (Claude, ChatGPT, …) connect through the MCP server
// (apps/mcp-server) with an `rmcp_…` key. Every tool below is executed by the
// API with the client's TenantContext (acting role, branch scope, allow-list);
// there is no SQL tool and no database credential anywhere in the MCP path.
import { z } from 'zod';
import { isoDate, isoDateTime, optionalText, text, uuid } from './common';
import type { ModuleKey } from './modules';
import { memberRole } from './common';
import type { Permission, Role } from './permissions';
import { ORDER_STATUSES, RESERVATION_STATUSES } from './state-machines';

export const mcpContractsVersion = 1 as const;

/** Every MCP key starts with this prefix (the API guard routes on it). */
export const MCP_KEY_PREFIX = 'rmcp_';

export const MCP_TOOL_NAMES = [
  'get_restaurant_profile', 'list_branches',
  'list_orders', 'get_order',
  'list_reservations',
  'search_customers',
  'get_sales_summary', 'list_top_items',
  'get_inventory_status', 'list_low_stock',
  'list_insights',
  'create_customer_segment', 'prepare_campaign_draft', 'request_campaign_send',
  'create_payment_link',
  'update_product_availability',
  'get_approval_status',
  // FT-17: menu, finance, payments (read-only, masked), delivery status and a bounded schema-based query (no SQL).
  'list_menu', 'get_finance_summary', 'list_payments', 'list_delivery_jobs', 'query_data',
] as const;
export type McpToolName = (typeof MCP_TOOL_NAMES)[number];
export const mcpToolName = z.enum(MCP_TOOL_NAMES);

export interface McpToolMeta {
  title: string;
  titleAr: string;
  /** Role permission the client's acting role needs (null: any role). */
  permission: Permission | null;
  /** Module the tenant must be entitled to (in addition to `mcp`). */
  module: ModuleKey;
  /** Sensitive tools never execute directly: they create an approval request. */
  sensitive: boolean;
  /** Read-only tools never change state. */
  readOnly: boolean;
  /** Per-tool, per-client limit (calls per minute), on top of the client limit. */
  ratePerMin: number;
}

