/** Response of `POST /v1/o/:orgId/mcp/tools/:tool`. */
export interface McpToolCallResponse {
  status: 'ok' | 'approval_required';
  tool: McpToolName;
  output: unknown;
  replayed: boolean;
}

/** Entry of `GET /v1/o/:orgId/mcp/tools` (MCP clients) — JSON Schemas ready for MCP `tools/list`. */
export interface McpToolDescriptor {
  name: McpToolName;
  title: string;
  description: string;
  inputSchema: Record<string, unknown>;
  outputSchema: Record<string, unknown>;
  annotations: { title: string; readOnlyHint: boolean; destructiveHint: boolean; idempotentHint: boolean; openWorldHint: boolean };
  sensitive: boolean;
}

/** `GET /v1/mcp/whoami` */
export interface McpWhoAmI {
  clientId: string;
  name: string;
  orgId: string;
  orgName: string;
  actingRole: Role;
  branchIds: string[] | null;
  allowedTools: McpToolName[];
  rateLimitPerMin: number;
  /** How the caller authenticated; OAuth access tokens also carry their audience (the MCP resource URI). */
  auth?: 'key' | 'oauth';
  resource?: string | null;
}
